transport_fixture:
import {writeFileSync} from 'node:fs';
let sends = 0, sockets = 0;
globalThis.WebSocket = class extends EventTarget {
  static OPEN = 1;
  readyState = 0;
  constructor() {
    super(); sockets++;
    queueMicrotask(() => { this.readyState = 1; this.dispatchEvent(new Event('open')); });
  }
  send(body) {
    if (JSON.parse(body).type !== 'response.create') throw Error('Unexpected fixture request');
    if (sends >= 4) throw Error('Fixture request ceiling');
    sends++;
    writeFileSync('/workspace/transport-count.json', JSON.stringify({sends, sockets,
      budget_instruction_present: JSON.stringify(JSON.parse(body)).includes('You have a hard budget of 1 model turns.')}));
    const id = 'fixture-' + sends;
    const item = {id, type:'message', role:'assistant', status:'completed',
      content:[{type:'output_text', text:'READY.', annotations:[]}]};
    const events = [
      {type:'response.created', response:{id, status:'in_progress', output:[]}},
      {type:'response.output_item.added', output_index:0,
       item:{...item, status:'in_progress', content:[]}},
      {type:'response.content_part.added', output_index:0, content_index:0, item_id:id,
       part:{type:'output_text', text:'', annotations:[]}},
      {type:'response.output_text.delta', output_index:0, content_index:0, item_id:id, delta:'READY.'},
      {type:'response.output_text.done', output_index:0, content_index:0, item_id:id, text:'READY.'},
      {type:'response.output_item.done', output_index:0, item},
      {type:'response.completed', response:{id, status:'completed', output:[item],
       usage:{input_tokens:1, output_tokens:1}}},
    ];
    queueMicrotask(() => { for (const event of events) this.dispatchEvent(
      new MessageEvent('message', {data: JSON.stringify(event)})); });
  }
  close() { this.readyState = 3; }
};
const fixtureSocket = globalThis.WebSocket;
Object.defineProperty(globalThis, 'WebSocket', {configurable:true,
  get:() => fixtureSocket, set:() => {}});

startup_extension:
import {appendFileSync} from 'node:fs';
export default function(pi: any) {
  appendFileSync('/workspace/startup-count', 'initialized\n');
  if (process.env.FORCE_CONTINUATION === '1') {
    pi.on('turn_end', (event: any) => event.outcome === 'completed' ? {
      entries: [{type:'custom_message',customType:'fixture',content:'Continue the fixture.',display:false}],
      continue: true,
    } : undefined);
  }
}
